projects:
WITH assignments AS (
SELECT 'project_manager'::text AS kind,p.id::text AS id,p.project_manager_id::text AS owner_id,p.version::bigint AS version,p.project_number||' · '||p.name::text AS title,p.lifecycle_status::text AS state,'/dashboard?screen=projects&project='||p.id::text::text AS link,jsonb_build_array('projects.master.read','projects.master.write')::jsonb AS required_permissions,''::text AS due_date FROM projects p WHERE p.is_active AND p.lifecycle_status<>'closed'
) SELECT jsonb_build_object('Source','projects','Kind',kind,'ID',id,'OwnerID',owner_id,'Version',version,'Title',title,'State',state,'Link',link,'RequiredPermissions',required_permissions,'DueDate',due_date)::jsonb AS payload FROM assignments WHERE ($1::text='' OR owner_id=$1) AND ($3::text='' OR id=$3) AND ($2::text='' OR kind=$2) ORDER BY kind,id,owner_id LIMIT 10001;

project_access:
WITH assignments AS (
SELECT 'project_responsibility'::text AS kind,a.id::text AS id,a.user_id::text AS owner_id,a.version::bigint AS version,a.responsibility::text AS title,'active'::text AS state,'/dashboard?screen=projects&project='||a.project_id::text::text AS link,a.permission_codes::jsonb AS required_permissions,''::text AS due_date, a.project_id::text AS project_id FROM project_responsibility_profiles a WHERE a.is_active
) SELECT jsonb_build_object('Source','project_access','Kind',kind,'ID',id,'OwnerID',owner_id,'Version',version,'Title',title,'State',state,'Link',link,'RequiredPermissions',required_permissions,'DueDate',due_date,'ProjectID',project_id)::jsonb AS payload FROM assignments WHERE ($1::text='' OR owner_id=$1) AND ($3::text='' OR id=$3) AND ($2::text='' OR kind=$2) ORDER BY kind,id,owner_id LIMIT 10001;

organisation_governance:
WITH assignments AS (
SELECT 'director'::text AS kind,p.id::text AS id,p.user_id::text AS owner_id,p.version::bigint AS version,'Organisation Director'::text AS title,'effective'::text AS state,'/dashboard?screen=director'::text AS link,jsonb_build_array('admin.governance.read')::jsonb AS required_permissions,''::text AS due_date FROM organisation_director_designation p WHERE p.is_active
) SELECT jsonb_build_object('Source','organisation_governance','Kind',kind,'ID',id,'OwnerID',owner_id,'Version',version,'Title',title,'State',state,'Link',link,'RequiredPermissions',required_permissions,'DueDate',due_date)::jsonb AS payload FROM assignments WHERE ($1::text='' OR owner_id=$1) AND ($3::text='' OR id=$3) AND ($2::text='' OR kind=$2) ORDER BY kind,id,owner_id LIMIT 10001;

tender_fms:
WITH assignments AS (
SELECT 'tender_owner'::text AS kind,p.id::text AS id,p.owner_id::text AS owner_id,CASE WHEN p.record_kind='named' THEN p.assignment_version ELSE p.version::bigint END AS version,p.title::text AS title,'active'::text AS state,'/dashboard?screen=tender-fms'::text AS link,CASE WHEN p.record_kind='named' THEN jsonb_build_array('tenders.register.view','tenders.register.read','tenders.register.write','tenders.processing.read','tenders.processing.write','tenders.register.assign','tenders.evaluation.read','tenders.evaluation.write','communication.inbox.read','communication.inbox.write') ELSE jsonb_build_array('tenders.register.view','tenders.register.read','tenders.register.write','tenders.processing.read','tenders.processing.write') END::jsonb AS required_permissions,''::text AS due_date FROM tender.tender_fms_intakes p WHERE p.is_active
) SELECT jsonb_build_object('Source','tender_fms','Kind',kind,'ID',id,'OwnerID',owner_id,'Version',version,'Title',title,'State',state,'Link',link,'RequiredPermissions',required_permissions,'DueDate',due_date)::jsonb AS payload FROM assignments WHERE ($1::text='' OR owner_id=$1) AND ($3::text='' OR id=$3) AND ($2::text='' OR kind=$2) ORDER BY kind,id,owner_id LIMIT 10001;
